"""Export rendered layout fixtures with the actual compiled Odoo styles (no DB changes)."""
from pathlib import Path
import hashlib

root = Path('C:/Odoo/odoo/odoo/addons/ar_visitors/tests/responsive_preview')
root.mkdir(exist_ok=True)
for name, filename in [('web.assets_frontend', 'frontend.css'), ('web.assets_backend', 'backend.css'), ('survey.survey_assets', 'survey.css')]:
    bundle = env['ir.qweb']._get_asset_bundle(name, css=True, js=False)
    css = bundle.css()
    assert not bundle.css_errors
    (root / filename).write_bytes(b'\n'.join(item.raw for item in css))

def page(name, body, styles, cls='', script=''):
    script = script.replace('kiosk_quiz.js"', 'kiosk_quiz.js?v=26"')
    links = ''.join('<link rel="stylesheet" href="' + style + '.css?v=' + hashlib.sha256((root / (style + '.css')).read_bytes()).hexdigest()[:12] + '">' for style in styles)
    (root / (name + '.html')).write_text('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' + links + '</head><body class="' + cls + '">' + body + script + '</body></html>', encoding='utf-8')

(root / 'poster.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="400" height="700"><rect width="400" height="700" fill="#173b78"/><text x="25" y="60" fill="white" font-size="28">Consignes de sécurité</text>' + ''.join('<rect x="20" y="%s" width="360" height="115" rx="10" fill="#effaf3"/><text x="40" y="%s" fill="#173b78" font-size="24">%s. Règle de sécurité</text>' % (95 + i * 145, 155 + i * 145, i + 1) for i in range(4)) + '</svg>', encoding='utf-8')
text = 'Restez tout le temps accompagné par votre interlocuteur ou une personne autorisée.'
summary = ''.join('<li class="%s"><span class="ar_safety_summary_number">%s</span><span class="ar_safety_summary_emoji">%s</span></li>' % ('is-current' if i == 0 else '', i + 1, ['👤', '🦺', '🚶', '🚜', '⛔', '📱', '🚭', '📷', '⚙️', '⚠️', '🚨', '🧯', '☎️'][i]) for i in range(13))
page('safety', '<div class="ar_face_safety_overlay"><div class="ar_face_safety_card"><header class="ar_safety_header"><span class="ar_safety_header_icon">🛡</span><h2>Prendre connaissance des consignes de sécurité</h2></header><ol class="ar_safety_summary">' + summary + '</ol><div class="ar_safety_list"><article class="ar_safety_instruction ar_safety_slide"><div class="ar_safety_instruction_content"><span class="ar_safety_emoji">👤</span><div class="ar_safety_step_label">Consigne 1 / 13</div><p class="ar_safety_text">' + text + '</p></div><div class="ar_safety_gallery ar_safety_readable_images"><img src="poster.svg" alt="Consigne"></div></article></div><footer class="ar_safety_footer ar_safety_guided_footer"><div class="ar_safety_progress"><strong>Consigne 1 / 13</strong><small>Parcourez toutes les consignes pour revenir à l’accueil.</small></div><button class="ar_face_home_button ar_safety_next_button">Consigne suivante ➜</button><button class="ar_face_home_button" disabled>Retour à l’accueil</button></footer></div></div>', ['backend'])
page('host-frame', '<main class="ar-kiosk-card"><header><span class="ar-brand">AR</span><h1>Visiteurs</h1><span class="ar-reference">VIS - TEST</span><button class="ar-visit-close">×</button></header><div class="ar-person-summary"><img src="poster.svg" alt="Photo"><div><strong>Visiteur de démonstration</strong><small>CIN / passeport ••••TEST</small></div></div><section class="ar-step"><h2>Votre visite</h2><form class="ar-details-form"><div class="ar-visit-fields"><div><label>Personne à visiter</label><select><option>—</option></select></div><div><label>Motif</label><input></div></div><label>Signature du visiteur</label><canvas id="ar-entry-signature" width="800" height="240" style="width:100%;border:1px solid #cbd5e1;border-radius:12px"></canvas><div class="ar-visit-actions"><button>Effacer la signature</button><button class="ar-primary">Enregistrer et notifier</button></div></form></section></main>', ['frontend'], 'ar-visitors-kiosk')
page('host', '<div class="o_dialog ar_visit_details_dialog"><div class="modal d-block"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-body"><iframe src="host-frame.html" style="width:100%;border:0;height:78vh"></iframe></div></div></div></div></div>', ['backend'])
question = '<div id="wrapwrap" class="o_survey_background"><main><div class="wrap o_survey_wrap d-flex"><div class="o_container_small o_survey_form d-flex flex-column mb-5"><form class="o_survey-fill-form d-flex flex-grow-1 align-items-center"><div class="o_survey_form_content w-100"><div class="o_survey_page_per_question"><div class="mt-5"><div class="js_question-wrapper pb-4"><div class="mb-4"><h3>Quelle est la bonne pratique pour circuler en sécurité ?</h3></div><div class="row g-2 o_survey_answer_wrapper o_survey_form_choice">' + ''.join('<div class="col-sm-12 col-lg-6"><label class="o_survey_choice_btn py-1 px-3 w-100 h-100 rounded">Réponse ' + str(i+1) + '<div class="o_survey_choice_img d-flex my-3 justify-content-center"><img src="poster.svg" class="mw-100 h-auto"></div></label></div>' for i in range(3)) + '</div></div></div><div class="text-center mt16"><button class="btn btn-primary">Continuer</button></div></div></div></form></div></div></main><div class="py-3 text-end">33% terminé</div></div>'
page('question-frame', question, ['frontend', 'survey'])
page('question', '<button id="ar-open-quiz" data-quiz-url="question-frame.html" hidden>Quiz</button><dialog id="ar-quiz-dialog" data-status-url="/not-a-status"><header><h2>Quiz de sécurité</h2><button id="ar-close-quiz">×</button></header><iframe title="Quiz"></iframe></dialog>', ['frontend'], 'ar-visitors-kiosk', '<script src="../../static/src/js/kiosk_quiz.js"></script>')
page('feedback', '<dialog class="ar_quiz_feedback"><h2>Prenez connaissance de la correction</h2><section><h3>Quelle est la bonne pratique pour circuler en sécurité ?</h3><p>Bonne réponse :</p><ul class="ar_quiz_image_answers"><li><img src="poster.svg"><span>Réponse A</span></li><li><img src="poster.svg"><span>Réponse B</span></li></ul></section><button class="btn btn-primary">Question suivante</button></dialog>', ['frontend', 'survey'], script='<script>document.querySelector("dialog").showModal()</script>')
page('intro', '<div class="ar_survey_safety"><h2>🛡 Consignes de sécurité</h2><article><div class="ar_survey_safety_content"><span class="ar_survey_safety_emoji">👤</span><p>' + text + '</p></div><div class="ar_survey_safety_images"><img src="poster.svg" alt="Consigne"></div></article></div>', ['frontend', 'survey'])
env.cr.rollback()
print('RESPONSIVE PREVIEWS READY:', root)
